def test_parse_pay_annualizes_biweekly_and_semimonthly_usd():
    from src.engine import _apply_listing, _parse_pay

    assert _parse_pay("$3,000 biweekly") == (None, 75_000)
    assert _parse_pay("$3,000 bi-weekly") == (None, 75_000)
    assert _parse_pay("$3,000 every two weeks") == (None, 75_000)
    assert _parse_pay("$3,000 every other week") == (None, 75_000)
    assert _parse_pay("$3,000 every 2 weeks") == (None, 75_000)
    assert _parse_pay("$3,000 every-two-weeks") == (None, 75_000)
    assert _parse_pay("$3,000 per fortnight") == (None, 75_000)
    assert _parse_pay("$3,000 fortnightly") == (None, 75_000)
    assert _parse_pay("$3,000 / biweekly") == (None, 75_000)
    assert _parse_pay("$3,000/fortnight") == (None, 75_000)
    assert _parse_pay("$3,000 / semi-monthly") == (None, 72_000)
    assert _parse_pay("$3,000 biweekly travel") == (None, None)
    assert _parse_pay("$3,000 semi-monthly housing") == (None, None)
    assert _parse_pay("Salary $180,000 plus $3,000 biweekly travel") == (None, 180_000)
    assert _parse_pay("$1,500-$2,000 biweekly") == (37_500, 50_000)
    assert _parse_pay("$1,500-$2,000 every other week") == (37_500, 50_000)
    assert _parse_pay("$3,000 twice a month") == (None, 72_000)
    assert _parse_pay("$3,000 semi-monthly") == (None, 72_000)
    assert _parse_pay("$3,000 per week") == (None, 150_000)
    assert _parse_pay("$15,000 per month") == (None, 180_000)
    opp = Opportunity(title="Engineer", url="https://jobs.example/bi")
    assert _apply_listing(opp, "<p>Pay $3,000 biweekly</p>") is True
    assert opp.pay_high == 75_000
    other = Opportunity(title="Engineer", url="https://jobs.example/other-week")
    assert _apply_listing(other, "<p>Pay $3,000 every other week</p>") is True
    assert other.pay_high == 75_000
    fortnight = Opportunity(title="Engineer", url="https://jobs.example/fortnight")
    assert _apply_listing(fortnight, "<p>Pay $3,000 per fortnight</p>") is True
    assert fortnight.pay_high == 75_000
    semi = Opportunity(title="Engineer", url="https://jobs.example/sm")
    assert _apply_listing(semi, "<p>Pay $3,000 semi-monthly</p>") is True
    assert semi.pay_high == 72_000


def test_apply_listing_json_ld_biweekly_pay():
    from src.engine import _apply_listing

    html = """
    <script type="application/ld+json">
    {"@type":"JobPosting","title":"Engineer",
     "baseSalary":{"@type":"MonetaryAmount","currency":"USD",
       "value":{"@type":"QuantitativeValue","value":3000,"unitText":"BIWEEKLY"}}}
    </script>
    """
    opp = Opportunity(title="Engineer", url="https://jobs.example/ld-bi")
    assert _apply_listing(opp, html) is True
    assert opp.pay_high == 75_000
    thousands = """
    <script type="application/ld+json">
    {"@type":"JobPosting","title":"Engineer",
     "baseSalary":{"@type":"MonetaryAmount","currency":"USD",
       "value":{"@type":"QuantitativeValue","value":3,"unitText":"BIWEEKLY"}}}
    </script>
    """
    k = Opportunity(title="Engineer", url="https://jobs.example/ld-bi-k")
    assert _apply_listing(k, thousands) is True
    assert k.pay_high == 75_000
    semi_k = """
    <script type="application/ld+json">
    {"@type":"JobPosting","title":"Engineer",
     "baseSalary":{"@type":"MonetaryAmount","currency":"USD",
       "value":{"@type":"QuantitativeValue","value":3,"unitText":"SEMI-MONTHLY"}}}
    </script>
    """
    sm = Opportunity(title="Engineer", url="https://jobs.example/ld-sm-k")
    assert _apply_listing(sm, semi_k) is True
    assert sm.pay_high == 72_000
    two_weeks = """
    <script type="application/ld+json">
    {"@type":"JobPosting","title":"Engineer",
     "baseSalary":{"@type":"MonetaryAmount","currency":"USD",
       "value":{"@type":"QuantitativeValue","minValue":3000,"maxValue":4000,"unitText":"every two weeks"}}}
    </script>
    <p>Office. Full time.</p>
    """
    two = Opportunity(title="Engineer", url="https://jobs.example/ld-every-two-weeks")
    assert _apply_listing(two, two_weeks) is True
    assert two.pay_low == 75_000
    assert two.pay_high == 100_000
    snake = """
    <script type="application/ld+json">
    {"@type":"JobPosting","title":"Engineer",
     "baseSalary":{"@type":"MonetaryAmount","currency":"USD",
       "value":{"@type":"QuantitativeValue","minValue":3000,"maxValue":4000,"unitText":"EVERY_TWO_WEEKS"}}}
    </script>
    <p>Office. Full time.</p>
    """
    snake_row = Opportunity(title="Engineer", url="https://jobs.example/ld-EVERY_TWO_WEEKS")
    assert _apply_listing(snake_row, snake) is True
    assert snake_row.pay_low == 75_000
    assert snake_row.pay_high == 100_000
    twice = """
    <script type="application/ld+json">
    {"@type":"JobPosting","title":"Engineer",
     "baseSalary":{"@type":"MonetaryAmount","currency":"USD",
       "value":{"@type":"QuantitativeValue","minValue":3000,"maxValue":4000,"unitText":"twice per month"}}}
    </script>
    <p>Office. Full time.</p>
    """
    twice_row = Opportunity(title="Engineer", url="https://jobs.example/ld-twice-per-month")
    assert _apply_listing(twice_row, twice) is True
    assert twice_row.pay_low == 72_000
    assert twice_row.pay_high == 96_000


