def _personio_xml(positions) -> str:
    rows = []
    for pos in positions:
        extras = "".join(
            f"<office>{office}</office>" for office in pos.get("additionalOffices") or []
        )
        extra_xml = (
            f"<additionalOffices>{extras}</additionalOffices>" if extras else ""
        )
        descs = "".join(
            f"<jobDescription><name>x</name><value>{d}</value></jobDescription>"
            for d in pos.get("descriptions") or []
        )
        rows.append(
            "<position>"
            f"<id>{pos['id']}</id>"
            f"<subcompany>{pos.get('subcompany') or ''}</subcompany>"
            f"<office>{pos.get('office') or ''}</office>"
            f"{extra_xml}"
            f"<name>{pos.get('name') or ''}</name>"
            f"<jobDescriptions>{descs}</jobDescriptions>"
            f"<schedule>{pos.get('schedule') or ''}</schedule>"
            "</position>"
        )
    return '<?xml version="1.0" encoding="UTF-8"?><workzag-jobs>' + "".join(rows) + "</workzag-jobs>"


def test_listing_text_reads_personio_xml_remote_office(monkeypatch):
    engine = Engine()
    seen: list[str] = []
    xml = _personio_xml(
        [
            {
                "id": "2774857",
                "subcompany": "FINNOFLEET P-D-F GmbH",
                "office": "Berlin",
                "additionalOffices": ["Remote deutschlandweit"],
                "name": "AI Engineer (m/w/d) – Machine Learning &amp; GenAI",
                "descriptions": ["<p>Build AI.</p>"],
                "schedule": "full-time",
            }
        ]
    )

    async def fake_get(_client, url: str):
        seen.append(url)
        return xml

    monkeypatch.setattr("src.engine._http_get_text", fake_get)
    url = "https://finnofleet.jobs.personio.de/job/2774857?language=de"
    text = asyncio.run(engine._listing_text(url))
    assert seen == ["https://finnofleet.jobs.personio.de/xml"]
    from src.engine import _apply_listing, _html_is_index

    assert _html_is_index(text, url) is False
    opp = Opportunity(title="x", url=url)
    assert _apply_listing(opp, text) is False
    assert opp.company == "FINNOFLEET P-D-F GmbH"
    assert opp.remote is True
    assert opp.hours_per_week == 40
    assert "Build AI" in text


def test_personio_city_offices_stay_office():
    from src.engine import _apply_listing, _personio_to_html

    html = _personio_to_html(
        {
            "name": "(Senior) Machine Learning Engineer (m/w/d)",
            "subcompany": "The Nunatak Group GmbH",
            "offices": ["München", "Berlin"],
            "schedule": "full-time",
            "descriptions": ["<p>Consulting.</p>"],
        }
    )
    opp = Opportunity(
        title="x",
        url="https://nunatak.jobs.personio.de/job/2724247?language=de",
    )
    assert _apply_listing(opp, html) is False
    assert opp.company == "The Nunatak Group GmbH"
    assert opp.remote is False
    from src.engine import _personio_position

    xml = (
        '<?xml version="1.0" encoding="UTF-8"?><workzag-jobs><position>'
        "<id>2724248</id><subcompany>Acme</subcompany><office>Austin</office>"
        "<name>Engineer</name><schedule>full-time</schedule><jobDescriptions>"
        "<jobDescription><name>Description</name>"
        "<value>Account Executive $400,000 - $500,000</value></jobDescription>"
        "<jobDescription><name>Salary</name>"
        "<value>$180,000 - $220,000</value></jobDescription>"
        "<jobDescription><name>Referral reward</name>"
        "<value>$2,000</value></jobDescription>"
        "</jobDescriptions></position></workzag-jobs>"
    )
    paid = Opportunity(title="x", url="https://acme.jobs.personio.de/job/2724248")
    assert _apply_listing(paid, _personio_to_html(_personio_position(xml, "2724248"))) is True
    assert paid.pay_low == 180_000
    assert paid.pay_high == 220_000
    assert paid.remote is False
    desired = (
        '<?xml version="1.0" encoding="UTF-8"?><workzag-jobs><position>'
        "<id>2724249</id><subcompany>Acme</subcompany><office>Austin</office>"
        "<name>Engineer</name><schedule>full-time</schedule><jobDescriptions>"
        "<jobDescription><name>Description</name>"
        "<value>Account Executive $400,000</value></jobDescription>"
        "<jobDescription><name>Desired Salary</name>"
        "<value>$180,000 - $220,000</value></jobDescription>"
        "</jobDescriptions></position></workzag-jobs>"
    )
    prompt = Opportunity(title="x", url="https://acme.jobs.personio.de/job/2724249")
    _apply_listing(prompt, _personio_to_html(_personio_position(desired, "2724249")))
    assert prompt.pay_high != 180_000
    assert prompt.pay_high != 220_000
    hourly_xml = (
        '<?xml version="1.0" encoding="UTF-8"?><workzag-jobs><position>'
        "<id>2724250</id><subcompany>Acme</subcompany><office>Austin</office>"
        "<name>Engineer</name><schedule>full-time</schedule><jobDescriptions>"
        "<jobDescription><name>Description</name>"
        "<value>Office. Full time.</value></jobDescription>"
        "<jobDescription><name>Hourly Rate</name>"
        "<value>$80 - $100</value></jobDescription>"
        "</jobDescriptions></position></workzag-jobs>"
    )
    hourly = Opportunity(title="x", url="https://acme.jobs.personio.de/job/2724250")
    assert _apply_listing(
        hourly, _personio_to_html(_personio_position(hourly_xml, "2724250"))
    ) is True
    assert hourly.pay_low == 160_000
    assert hourly.pay_high == 200_000
    hours_xml = (
        '<?xml version="1.0" encoding="UTF-8"?><workzag-jobs><position>'
        "<id>2724251</id><subcompany>Acme</subcompany><office>Austin</office>"
        "<name>Engineer</name><schedule>full-time</schedule><jobDescriptions>"
        "<jobDescription><name>Description</name>"
        "<value>Office. Full time.</value></jobDescription>"
        "<jobDescription><name>Hourly Rate</name>"
        "<value>$80 - $100</value></jobDescription>"
        "<jobDescription><name>Hours per week</name>"
        "<value>32</value></jobDescription>"
        "</jobDescriptions></position></workzag-jobs>"
    )
    hours = Opportunity(title="x", url="https://acme.jobs.personio.de/job/2724251")
    assert _apply_listing(
        hours, _personio_to_html(_personio_position(hours_xml, "2724251"))
    ) is True
    assert hours.hours_per_week == 32
    assert hours.pay_low == 128_000
    assert hours.pay_high == 160_000


