def test_listing_text_reads_comeet_api_not_referral_pay(monkeypatch):
    engine = Engine()
    seen: list[str] = []
    page = '{"company_uid": "43.001", "token": "AABBCCDDEEFF00112233445566778899"}'
    payload = {
        "name": "Platform Senior Software Engineer",
        "company_name": "VAST Data",
        "employment_type": "Full-time",
        "workplace_type": "Hybrid",
        "location": {"name": "United States", "is_remote": True},
        "company_referrals_reward": "$2,000",
        "details": [
            {"name": "Description", "value": "<p>Build AI infrastructure.</p>"},
            {"name": "Referral reward", "value": "$2,000"},
        ],
    }

    async def fake_get(_client, url: str):
        seen.append(url)
        if "careers-api" in url:
            assert "AABBCCDDEEFF00112233445566778899" in url
            return json.dumps(payload)
        return page

    monkeypatch.setattr("src.engine._http_get_text", fake_get)
    url = (
        "https://www.comeet.com/jobs/vastdata/43.001/"
        "senior-software-engineer-platform/96.616"
    )
    text = asyncio.run(engine._listing_text(url))
    assert seen[0] == url
    assert "careers-api/2.0/company/43.001/positions/96.616" in seen[1]
    from src.engine import _apply_listing

    opp = Opportunity(title="x", url=url)
    listed = _apply_listing(opp, text)
    assert listed is False
    assert opp.company == "VAST Data"
    assert opp.remote is True
    assert opp.pay_high is None
    assert opp.hours_per_week == 40
    assert "$2,000" not in text
    from src.engine import _comeet_to_html

    paid = Opportunity(
        title="x",
        url="https://www.comeet.com/jobs/acme/1.000/engineer/2.000",
    )
    assert _apply_listing(
        paid,
        _comeet_to_html(
            {
                "name": "Engineer",
                "company_name": "Acme",
                "employment_type": "Full-time",
                "workplace_type": "Onsite",
                "location": {"name": "Austin"},
                "details": [
                    {"name": "About", "value": "Account Executive $400,000 - $500,000"},
                    {"name": "Salary", "value": "$180,000 - $220,000"},
                    {"name": "Referral reward", "value": "$2,000"},
                ],
            }
        ),
    ) is True
    assert paid.pay_low == 180_000
    assert paid.pay_high == 220_000
    assert paid.remote is False
    prompt = Opportunity(
        title="x",
        url="https://www.comeet.com/jobs/acme/1.000/engineer/2.001",
    )
    _apply_listing(
        prompt,
        _comeet_to_html(
            {
                "name": "Engineer",
                "company_name": "Acme",
                "employment_type": "Full-time",
                "workplace_type": "Onsite",
                "location": {"name": "Austin"},
                "details": [
                    {"name": "About", "value": "Account Executive $400,000"},
                    {"name": "Desired Salary", "value": "$180,000 - $220,000"},
                ],
            }
        ),
    )
    assert prompt.pay_high != 180_000
    assert prompt.pay_high != 220_000
    hourly = Opportunity(
        title="x",
        url="https://www.comeet.com/jobs/acme/1.000/engineer/2.002",
    )
    assert _apply_listing(
        hourly,
        _comeet_to_html(
            {
                "name": "Engineer",
                "company_name": "Acme",
                "employment_type": "Full-time",
                "workplace_type": "Onsite",
                "location": {"name": "Austin"},
                "details": [
                    {"name": "About", "value": "Office. Full time."},
                    {"name": "Hourly Rate", "value": "$80 - $100"},
                ],
            }
        ),
    ) is True
    assert hourly.pay_low == 160_000
    assert hourly.pay_high == 200_000
    hpw = Opportunity(
        title="x",
        url="https://www.comeet.com/jobs/acme/1.000/engineer/2.003",
    )
    assert _apply_listing(
        hpw,
        _comeet_to_html(
            {
                "name": "Engineer",
                "company_name": "Acme",
                "employment_type": "Full-time",
                "workplace_type": "Onsite",
                "location": {"name": "Austin"},
                "details": [
                    {"name": "About", "value": "Office."},
                    {"name": "Hourly Rate", "value": "$80 - $100"},
                    {"name": "Hours per week", "value": "32"},
                ],
            }
        ),
    ) is True
    assert hpw.hours_per_week == 32
    assert hpw.pay_low == 128_000
    assert hpw.pay_high == 160_000


